add(5,'Inicializar con constructor','order','class Paquete {\n  int peso;\n  Paquete(int peso) { this.peso = peso; }\n}\nPaquete p = new Paquete(4);\nSystem.out.println(p.peso);','Crea un Paquete de peso 4 e imprímelo.',output(4),{chunks:['class Paquete {\n  int peso;\n  Paquete(int peso) { this.peso = peso; }\n}','Paquete p = new Paquete(4);','System.out.println(p.peso);']});
add(5,'this distingue atributo y parámetro','fix','class Bateria {\n  int energia;\n  Bateria(int energia) { this.energia = energia; }\n}\nBateria b = new Bateria(8);\nSystem.out.println(b.energia);','Inicializa el atributo e imprime 8.',output(8),{starter:'class Bateria {\n  int energia;\n  Bateria(int energia) { energia = energia; }\n}\nBateria b = new Bateria(8);\nSystem.out.println(b.energia);',hint:'Sin this, ambos nombres se refieren al parámetro. El atributo queda en su valor inicial 0.'});
add(5,'Dos objetos independientes','predict',contador+'\nContador a = new Contador(1);\nContador b = new Contador(1);\na.aumentar();\nSystem.out.println(a.getValor());\nSystem.out.println(b.getValor());','Predice el valor de a y b.',output(2,1),{choices:['2 y 2','1 y 1','2 y 1'],answer:2,explanation:'Cada new crea un objeto diferente. Cambiar a no modifica el estado de b.'});
