add(5,'Crear en lugar de compartir','fix',contador+'\nContador a = new Contador(1);\nContador b = new Contador(1);\nb.aumentar();\nSystem.out.println(a.getValor());\nSystem.out.println(b.getValor());','Haz independientes a y b; imprime 1 y 2.',output(1,2),{starter:contador+'\nContador a = new Contador(1);\nContador b = a;\nb.aumentar();\nSystem.out.println(a.getValor());\nSystem.out.println(b.getValor());',hint:'Copiar una referencia no clona el objeto. Usa otro new.'});
add(5,'Composición: una misión tiene un robot','order','class Equipo {\n  Robot miembro;\n  Equipo(Robot miembro) { this.miembro = miembro; }\n  void trabajar() { miembro.este(); }\n}\nEquipo equipo = new Equipo(robot);\nequipo.trabajar();','Usa un Equipo que contiene a Miaubit para llegar a (1, 2).',at(1,2),{chunks:['class Equipo {\n  Robot miembro;\n  Equipo(Robot miembro) { this.miembro = miembro; }\n  void trabajar() { miembro.este(); }\n}','Equipo equipo = new Equipo(robot);','equipo.trabajar();'],explanation:'Equipo no es un Robot: tiene una referencia a un Robot. Esa relación se llama composición.'});
add(5,'Tu clase con estado','write','class Contador {\n  int valor;\n  Contador(int inicial) { valor = inicial; }\n  void aumentar() { valor++; }\n  int getValor() { return valor; }\n}\nContador c = new Contador(5);\nc.aumentar();\nc.aumentar();\nSystem.out.println(c.getValor());','Completa Contador: inicia en 5, aumenta dos veces e imprime 7.',all(output(7),field('Contador','valor',7)),{starter:'class Contador {\n  int valor;\n  Contador(int inicial) { /* Inicializa */ }\n  void aumentar() { /* Modifica el atributo */ }\n  int getValor() { return valor; }\n}\nContador c = new Contador(5);\nc.aumentar();\nc.aumentar();\nSystem.out.println(c.getValor());',require:'class Contador'});
add(5,'Los métodos reciben referencias por valor','write','static void mover(Robot r) { r.este(); }\nstatic void reemplazar(Robot r) { r = new Robot("Nuevo"); }\nmover(robot);\nreemplazar(robot);\nSystem.out.println(robot.getNombre());\nSystem.out.println(robot.getX());','Mueve el objeto y comprueba que reasignar el parámetro no reemplaza robot. Imprime Miaubit y 1.',all(at(1,2),output('Miaubit',1)),{starter:'static void mover(Robot r) { /* Mueve r */ }\nstatic void reemplazar(Robot r) { r = new Robot("Nuevo"); }\nmover(robot);\nreemplazar(robot);\n// Imprime nombre y x de robot.',hint:'El parámetro copia una referencia. Puede modificar el objeto compartido; reasignar r cambia únicamente ese parámetro.'});
add(5,'Proyecto · Dos mensajeros','project','class Mensajero {\n  Robot robot;\n  Mensajero(Robot robot) { this.robot = robot; }\n  void llevar(int pasos) {\n    robot.recoger();\n    for (int i = 0; i < pasos; i++) { robot.este(); }\n    robot.dejar();\n  }\n}\nMensajero primero = new Mensajero(robot);\nMensajero segundo = new Mensajero(ayudante);\nprimero.llevar(2);\nsegundo.llevar(3);','Crea dos Mensajero: Miaubit entrega en (2, 2) y Luna en (3, 3).',all(at(2,2),at(3,3,'Luna'),s=>robot(s).delivered===1&&robot(s,'Luna').delivered===1),{starter:'class Mensajero {\n  Robot robot;\n  Mensajero(Robot robot) { this.robot = robot; }\n  void llevar(int pasos) { /* Recoge, viaja y entrega */ }\n}\n// Crea dos mensajeros con robots distintos y llama llevar().',initial:{helper:{},boxes:[[0,2,1],[0,3,1]],targets:[[2,2],[3,3]]},require:'Mensajero'});
