add(6,'Herencia con comportamiento adicional','order','class Explorador extends Robot {\n  Explorador(String nombre) { super(nombre); }\n  void explorar() { este(); norte(); }\n}\nExplorador e = new Explorador("Eco");\ne.explorar();','El Explorador Eco termina en (1, 2), desde su inicio (0, 3).',at(1,2,'Eco'),{chunks:['class Explorador extends Robot {\n  Explorador(String nombre) { super(nombre); }\n  void explorar() { este(); norte(); }\n}','Explorador e = new Explorador("Eco");','e.explorar();'],hint:'extends permite reutilizar los movimientos de Robot. super(nombre) inicializa el nombre del Robot base.'});
