add(6,'Encapsular un contador','write','class ContadorSeguro {\n  private int valor = 0;\n  public void sumar(int n) { if (n > 0) { valor += n; } }\n  public int getValor() { return valor; }\n}\nContadorSeguro c = new ContadorSeguro();\nc.sumar(3);\nc.sumar(-5);\nSystem.out.println(c.getValor());','Protege valor, acepta 3, rechaza -5 e imprime 3.',all(output(3),field('ContadorSeguro','valor',3)),{starter:'class ContadorSeguro {\n  private int valor = 0;\n  public void sumar(int n) { /* Valida n antes de modificar */ }\n  public int getValor() { return valor; }\n}\nContadorSeguro c = new ContadorSeguro();\nc.sumar(3);\nc.sumar(-5);\nSystem.out.println(c.getValor());'});
add(6,'Sobrescribir sin cambiar la llamada','write','class Ruta { int pasos() { return 1; } }\nclass RutaLarga extends Ruta { int pasos() { return 3; } }\nRuta r = new RutaLarga();\nfor (int i = 0; i < r.pasos(); i++) { robot.este(); }','Sobrescribe pasos(): la misma referencia Ruta lleva Miaubit a (3, 2).',at(3,2),{starter:'class Ruta { int pasos() { return 1; } }\nclass RutaLarga extends Ruta { /* Sobrescribe pasos() */ }\nRuta r = new RutaLarga();\nfor (int i = 0; i < r.pasos(); i++) { robot.este(); }',require:'class RutaLarga'});
add(6,'Proyecto · Estrategias intercambiables','project','interface Estrategia { void aplicar(Robot r); }\nclass Recta implements Estrategia {\n  public void aplicar(Robot r) { r.este(); r.este(); }\n}\nclass Desvio implements Estrategia {\n  public void aplicar(Robot r) { r.norte(); r.este(); r.este(); r.sur(); }\n}\nstatic void iniciar(Estrategia e, Robot r) { e.aplicar(r); }\nEstrategia estrategia = new Desvio();\niniciar(estrategia, robot);','Implementa dos estrategias. Usa Desvio para alcanzar (2, 2) alrededor del muro.',at(2,2),{starter:'interface Estrategia { void aplicar(Robot r); }\nclass Recta implements Estrategia {\n  public void aplicar(Robot r) { /* Ruta directa */ }\n}\nclass Desvio implements Estrategia {\n  public void aplicar(Robot r) { /* Rodea el muro */ }\n}\nstatic void iniciar(Estrategia e, Robot r) { e.aplicar(r); }\n// Elige y ejecuta una estrategia.',initial:{walls:[[1,2]],targets:[[2,2]]},require:'new Desvio',hint:'El método iniciar() depende de una interfaz. Cambiar de estrategia no obliga a reescribirlo.'});
