add(8,'No permitir un saldo negativo','fix','class Cuenta {\n  private int saldo = 10;\n  public void pagar(int coste) {\n    if (coste >= 0 && coste <= saldo) { saldo -= coste; }\n  }\n  public int getSaldo() { return saldo; }\n}\nCuenta c = new Cuenta();\nc.pagar(12);\nc.pagar(3);\nSystem.out.println(c.getSaldo());','Rechaza 12, acepta 3 e imprime saldo 7.',all(output(7),field('Cuenta','saldo',7)),{starter:'class Cuenta {\n  private int saldo = 10;\n  public void pagar(int coste) { saldo -= coste; }\n  public int getSaldo() { return saldo; }\n}\nCuenta c = new Cuenta();\nc.pagar(12);\nc.pagar(3);\nSystem.out.println(c.getSaldo());',hint:'La clase debe mantener su regla: saldo >= 0. Valida el coste antes de modificar el atributo.'});
add(8,'Consola · Contar aprobados','write','int[] notas = new int[]{5, 8, 6, 9};\nint aprobados = 0;\nfor (int i = 0; i < notas.length; i++) {\n  if (notas[i] >= 6) { aprobados++; }\n}\nSystem.out.println("Aprobados: " + aprobados);','Sin mover robots, cuenta notas >= 6 e imprime Aprobados: 3.',output('Aprobados: 3'),{starter:'int[] notas = new int[]{5, 8, 6, 9};\nint aprobados = 0;\n// Recorre, cuenta e imprime.',hint:'Transfiere la misma lógica a datos de consola. Cada nota que cumple la condición aumenta un contador.'});
add(8,'Consola · Un producto con reglas','write','class Producto {\n  private int stock;\n  Producto(int stock) { this.stock = stock; }\n  public boolean vender(int cantidad) {\n    if (cantidad > 0 && cantidad <= stock) {\n      stock -= cantidad;\n      return true;\n    }\n    return false;\n  }\n  public int getStock() { return stock; }\n}\nProducto p = new Producto(5);\nSystem.out.println(p.vender(2));\nSystem.out.println(p.vender(8));\nSystem.out.println(p.getStock());','Implementa vender(): acepta 2, rechaza 8. Imprime true, false y 3.',all(output(true,false,3),field('Producto','stock',3)),{starter:'class Producto {\n  private int stock;\n  Producto(int stock) { this.stock = stock; }\n  public boolean vender(int cantidad) {\n    // Valida, modifica y devuelve el resultado.\n    return false;\n  }\n  public int getStock() { return stock; }\n}\nProducto p = new Producto(5);\nSystem.out.println(p.vender(2));\nSystem.out.println(p.vender(8));\nSystem.out.println(p.getStock());'});
add(8,'Proyecto · Informe de inventario','project','class Producto {\n  private int unidades;\n  Producto(int unidades) { this.unidades = unidades; }\n  public int getUnidades() { return unidades; }\n}\nProducto[] inventario = new Producto[]{new Producto(3), new Producto(0), new Producto(5)};\nint total = 0;\nint agotados = 0;\nfor (int i = 0; i < inventario.length; i++) {\n  total += inventario[i].getUnidades();\n  if (inventario[i].getUnidades() == 0) { agotados++; }\n}\nSystem.out.println("Unidades: " + total);\nSystem.out.println("Agotados: " + agotados);','Modela productos con encapsulación. Imprime Unidades: 8 y Agotados: 1.',output('Unidades: 8','Agotados: 1'),{starter:'class Producto {\n  private int unidades;\n  Producto(int unidades) { this.unidades = unidades; }\n  public int getUnidades() { return unidades; }\n}\nProducto[] inventario = new Producto[]{new Producto(3), new Producto(0), new Producto(5)};\n// Calcula el total y la cantidad de productos agotados.',require:'inventario[i]',hint:'Mantén dos acumuladores independientes: uno suma unidades; el otro cuenta productos sin existencias.'});
add(8,'Proyecto final · Central de reparto','project','interface Ruta { void viajar(Robot r); }\nclass Desvio implements Ruta {\n  public void viajar(Robot r) { r.norte(); r.este(); r.este(); r.sur(); }\n}\nclass Recta implements Ruta {\n  public void viajar(Robot r) { for (int i = 0; i < 3; i++) { r.este(); } }\n}\nclass Servicio {\n  private Robot robot;\n  private Ruta ruta;\n  Servicio(Robot robot, Ruta ruta) { this.robot = robot; this.ruta = ruta; }\n  public void entregar() { robot.recoger(); ruta.viajar(robot); robot.dejar(); }\n}\nServicio[] servicios = new Servicio[]{new Servicio(robot, new Desvio()), new Servicio(ayudante, new Recta())};\nfor (int i = 0; i < servicios.length; i++) { servicios[i].entregar(); }\nSystem.out.println(robot.getEntregas() + ayudante.getEntregas());','Combina interfaces, composición y un arreglo de servicios. Miaubit entrega en (2, 2), Luna en (3, 3). Imprime 2.',all(at(2,2),at(3,3,'Luna'),s=>robot(s).delivered===1&&robot(s,'Luna').delivered===1,output(2)),{starter:'interface Ruta { void viajar(Robot r); }\nclass Desvio implements Ruta {\n  public void viajar(Robot r) { /* Rodea el muro */ }\n}\nclass Recta implements Ruta {\n  public void viajar(Robot r) { /* Tres pasos al este */ }\n}\nclass Servicio {\n  private Robot robot;\n  private Ruta ruta;\n  Servicio(Robot robot, Ruta ruta) { this.robot = robot; this.ruta = ruta; }\n  public void entregar() { /* Recoger, viajar y dejar */ }\n}\n// Crea un arreglo de servicios con las dos rutas.\n// Ejecuta cada servicio e imprime el total de entregas.',initial:{helper:{},boxes:[[0,2,1],[0,3,1]],walls:[[1,2]],targets:[[2,2],[3,3]]},require:'Servicio[]',hint:'La ruta sabe cómo viajar; el servicio coordina la entrega. Cada servicio guarda su robot y su estrategia.'});
